// === Tab: mySketch ===
let n = 300;
let delta;
let factor;


function setup(){
createCanvas(600, 600);
delta = 42*PI/n;


}

function draw(){
factor = 83*(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/width;
background(42);
translate(width/2, height/2);
stroke(42);
strokeWeight(random(3,5));
noFill();
ellipse(0,0,400,400);
stroke(250);
strokeWeight(random(-5,5));
for(i = 0; i < n; i ++){
point(200*cos(i*delta), 200*sin(i*delta));
strokeWeight(random(0.74,1.26));
line(200*cos(i*delta), 200*sin(i*delta), 200*cos(factor*i*delta), 200*sin(factor*i*delta));


}


}

